package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var safePattern = regexp.MustCompile(`^[a-zA-Z0-9_]+$`)

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// validateTableName checks for obviously dangerous characters
func validateTableName(name string) bool {
	// Block semicolons, comments, and quotes
	dangerous := []string{";", "--", "/*", "'", "\""}
	for _, d := range dangerous {
		if strings.Contains(name, d) {
			return false
		}
	}
	return true
}

// handleExport exports data from a user-specified view
func handleExport(w http.ResponseWriter, r *http.Request) {
	viewName := r.URL.Query().Get("view")
	format := r.URL.Query().Get("format")
	limit := r.URL.Query().Get("limit")

	if viewName == "" {
		http.Error(w, "view parameter required", http.StatusBadRequest)
		return
	}

	// Validate the view name to prevent injection
	if !validateTableName(viewName) {
		http.Error(w, "invalid view name", http.StatusBadRequest)
		return
	}

	// Additional check: view must start with "rpt_"
	if !strings.HasPrefix(viewName, "rpt_") {
		http.Error(w, "only report views allowed", http.StatusForbidden)
		return
	}

	// Sanitize limit - default to 1000
	if limit == "" {
		limit = "1000"
	}

	// Build query - view name cannot be parameterized in PostgreSQL
	// We validated it above so this should be safe
	query := fmt.Sprintf("SELECT * FROM %s LIMIT %s", viewName, limit)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "query failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	cols, _ := rows.Columns()
	w.Header().Set("Content-Type", "text/csv")
	if format == "download" {
		w.Header().Set("Content-Disposition", "attachment; filename=export.csv")
	}

	// Write CSV header
	fmt.Fprintln(w, strings.Join(cols, ","))

	// Write rows
	values := make([]interface{}, len(cols))
	valuePtrs := make([]interface{}, len(cols))
	for i := range values {
		valuePtrs[i] = &values[i]
	}

	for rows.Next() {
		rows.Scan(valuePtrs...)
		row := make([]string, len(cols))
		for i, v := range values {
			if v != nil {
				row[i] = fmt.Sprintf("%v", v)
			}
		}
		fmt.Fprintln(w, strings.Join(row, ","))
	}
}

// handleHealth is a simple health check
func handleHealth(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/export", handleExport)
	http.HandleFunc("/health", handleHealth)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
